from pycompss.api.task import task
from pycompss.api.api import compss_wait_on


# --- Task definitions ---

@task(returns=int)
def check_even(idx, value):
    """Return index if value is even, else None (PyCOMPSs task)."""
    return idx if value % 2 == 0 else None

@task(returns=int)
def combine_indices(idx1, idx2):
    """Return the smaller index, ignoring None values."""
    if idx1 is None:
        return idx2
    if idx2 is None:
        return idx1
    return min(idx1, idx2)

def main(x):
    """
    Find the index of the first even number in the list x.
    Use PyCOMPSs to compute in parallel.

    Example:

    input: [7, 3, 9, 5, 5, 7, 2, 9, 12, 11]
    output: 6

    input: [3, 8, 9, 9, 3, 4, 8, 6]
    output: 1
    """
    results = [check_even(idx, value) for idx, value in enumerate(x)]

    while len(results) > 1:
        for i in range(0, len(results), 2):
            if i + 1 < len(results):
                results[i // 2] = combine_indices(results[i], results[i + 1])
            else:
                results[i // 2] = results[i]  
        results = results[: (len(results) + 1) // 2]

    results = compss_wait_on(results)

    return results[0] if results[0] is not None else -1
